"""
modules/seeder.py — Lab sandbox population.

Creates 100 representative sample files across 10 sub-directories,
covering every extension in config.TARGET_EXTENSIONS.

Design notes
------------
* Follows the same class-level logger pattern as file_encryptor and cleanup.
* seed() returns a SeedResult; the caller (orchestrator) owns sys.exit decisions.
* Binary files (PDF, DOCX, XLSX, JPG, PNG) are base64 constants decoded at seed
  time — no runtime library dependencies on the target machine.
* Valid formats mean EDR heuristics behave realistically and files open normally.
"""

from __future__ import annotations

import base64
from dataclasses import dataclass
from pathlib import Path
from typing import List

import config
from utils.logger import get_logger


def _b(s: str) -> bytes:
    """Decode a base64-encoded binary seed file."""
    return base64.b64decode(s)


