    ('reports/weekly_report.txt',
     'Weekly Status Report — Week of Sep 15, 2026\n\nENGINEERING\n  ✓ Shipped v2.4.1 hotfix (API timeout fix)\n  ✓ Completed load testing for 10K concurrent users\n  → In progress: OAuth2 PKCE migration (ETA: Sep 22)\n\nPRODUCT\n  ✓ User interviews: 8 sessions with enterprise customers\n  → In progress: Roadmap planning for Q4\n\nSALES\n  ✓ Closed Delta Corp expansion ($800 MRR uplift)\n  → Pipeline: 3 enterprise deals in final negotiation\n'),
    ('reports/incident_report.xml',
     '<?xml version="1.0" encoding="UTF-8"?>\n<incident_report>\n  <id>INC-2026-0047</id>\n  <date>2026-09-12</date>\n  <severity>P2</severity>\n  <title>API Gateway Elevated Latency</title>\n  <duration_minutes>47</duration_minutes>\n  <affected_users>1240</affected_users>\n  <root_cause>Connection pool exhaustion due to slow DB queries after schema migration</root_cause>\n  <resolution>Rolled back migration; increased pool size; added query timeout</resolution>\n  <status>resolved</status>\n</incident_report>\n'),
