# fmt: on


# ---------------------------------------------------------------------------
# Result type
# ---------------------------------------------------------------------------
@dataclass
class SeedResult:
    written:  int  = 0      # files successfully written
    cleared:  int  = 0      # pre-existing target files removed (--force)
    skipped:  bool = False  # True when files existed and force=False → no-op
    aborted:  bool = False  # True when .locked files blocked the seed
    error:    str  = ""


# ---------------------------------------------------------------------------
# Seeder
# ---------------------------------------------------------------------------
class Seeder:
    """
    Writes sample files into the sandbox directory.

    Parameters
    ----------
    sandbox:  Sandbox root (config.SANDBOX_DIR).
    log_file: Optional log file path; injected by the orchestrator.
    """

    def __init__(self, sandbox: Path, log_file: Path | None = None) -> None:
        self._sandbox = sandbox
        self._logger  = get_logger(__name__, log_file=log_file)

    # ------------------------------------------------------------------
    # Inspection helpers
    # ------------------------------------------------------------------
    def has_locked_files(self) -> bool:
        """Return True if any .locked files exist under the sandbox."""
        if not self._sandbox.exists():
            return False
        return any(self._sandbox.rglob(f"*{config.ENCRYPTED_EXT}"))

    def find_targets(self) -> List[Path]:
        """Return all target-extension files currently in the sandbox."""
        if not self._sandbox.exists():
            return []
        return [
            p for p in self._sandbox.rglob("*")
            if p.is_file() and p.suffix.lower() in config.TARGET_EXTENSIONS
        ]

    # ------------------------------------------------------------------
    # Seed
    # ------------------------------------------------------------------
    def seed(self, force: bool = False) -> SeedResult:
        """
        Populate the sandbox with sample files from the manifest.

        Parameters
        ----------
        force:  When True, remove existing target files before writing.
                When False and target files are present, return a SeedResult
                with skipped=True without modifying anything.

        Returns
        -------
        SeedResult — the caller decides whether to sys.exit based on it.
        """
        result = SeedResult()

        # Abort if encrypt has already run (files are locked).
        if self.has_locked_files():
            msg = (
                f"Sandbox contains .locked files — "
                f"run --decrypt to restore before re-seeding."
            )
            self._logger.critical(msg)
            result.aborted = True
            result.error   = msg
            return result

        existing = self.find_targets()

        # Skip when target files exist and force is not requested.
        if existing and not force:
            self._logger.warning(
                "SANDBOX already contains %d target file(s). "
                "Re-run with --force to overwrite and re-seed.",
                len(existing),
            )
            result.skipped = True
            return result

        # Remove existing targets when running with --force.
        if existing and force:
            cleared = 0
            for p in existing:
                try:
                    p.unlink()
                    cleared += 1
                except OSError as exc:
                    self._logger.warning("Could not remove '%s': %s", p, exc)
            result.cleared = cleared
            self._logger.info("Cleared %d existing target file(s).", cleared)

        # Write the manifest.
        for rel_path, content in _SEED_FILES:
            target = self._sandbox / rel_path
            target.parent.mkdir(parents=True, exist_ok=True)
            try:
                if isinstance(content, bytes):
                    target.write_bytes(content)
                else:
                    target.write_text(content, encoding="utf-8")
                self._logger.debug(
                    "Seeded: %s", target.relative_to(config.BASE_DIR)
                )
                result.written += 1
            except OSError as exc:
                self._logger.warning("Could not write '%s': %s", target, exc)

        self._logger.info(
            "Seed complete: %d/%d files written to '%s'.",
            result.written, len(_SEED_FILES), self._sandbox,
        )
        return result
